Theorem chain_sound : forall n s fx R M model A LK s' log,
  INV s fx R M model A LK ->
  arunC segs CF n fuel s = CFin s' (AS 1%nat 0) 0 log -> s_resv s' = None -> forallb ev_chk log = true ->
